import ballerina/io;

function f((int|string)[] x) returns string {
    if x !is int[] {
        int[] y = [1, 2];
        if x == y {
            return "eq";
        }
        return "ne";
    }
    return "int[]";
}

public function main() {
    (int|string)[] a = [1, 2];
    io:println(f(a)); // @output eq
}

